def gen(rng):
    def fmt(n, edges):
        return str(n) + ''.join(f'\n{a} {b}' for a, b in edges)
    def make(n, mode):
        perm = list(range(n))
        rng.shuffle(perm)
        edges = []
        for i in range(1, n):
            if mode == 'path':
                p = i - 1
            elif mode == 'star':
                p = 0
            elif mode == 'deep':
                p = rng.randint(max(0, i - 3), i - 1)
            else:
                p = rng.randint(0, i - 1)
            a, b = perm[p], perm[i]
            if rng.random() < 0.5:
                a, b = b, a
            edges.append((a, b))
        rng.shuffle(edges)
        return fmt(n, edges)
    tests = ['1', '2\n0 1', '2\n1 0', '3\n0 1\n1 2', '3\n2 1\n1 0', '3\n1 0\n1 2',
             '5\n1 0\n1 2\n3 1\n4 3', '4\n0 1\n0 2\n0 3']
    for _ in range(40):
        n = rng.randint(2, 9)
        tests.append(make(n, rng.choice(['rand', 'rand', 'path', 'star', 'deep'])))
    N = 100000
    tests.append(make(N, 'rand'))
    tests.append(make(N, 'path'))
    tests.append(make(N, 'star'))
    tests.append(make(N, 'deep'))
    # path from city 0 outwards, all roads pointing away: answer n - 1
    perm = list(range(1, N))
    rng.shuffle(perm)
    chain = [0] + perm
    tests.append(fmt(N, [(chain[i], chain[i + 1]) for i in range(N - 1)]))
    return tests
